<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>Preview · {{ $case->name }}</title>
<style>body{font:17px/1.6 system-ui;background:#f7f8fb;color:#192238;max-width:850px;margin:40px auto;padding:24px}section{background:white;border:1px solid #dce1ea;border-radius:16px;padding:24px;margin:20px 0}button{font:inherit;background:#233c85;color:white;border:0;border-radius:9px;padding:12px 18px;margin:5px;cursor:pointer}button:disabled{opacity:.5}pre{white-space:pre-wrap;overflow-wrap:anywhere}a{color:#233c85}.muted{color:#59687e}</style></head><body>
<a href="{{ route('filament.admin.resources.scenario-cases.index') }}">← Patient cases</a><h1>Try this patient</h1><p class="muted">{{ $case->name }} · Draft preview. This creates a private test attempt with the current saved workflow and case.</p>
<section><h2>Opening brief</h2><p>{{ $case->workflow->brief }}</p><p>{{ $case->visible }}</p><button id="start">Start voice preview</button><button id="finish" disabled>Finish and review</button><p id="status" role="status">Microphone access requires localhost or HTTPS.</p></section>
<section><h2>Conversation</h2><div id="transcript"></div></section><section><h2>Feedback</h2><div id="report">Finish the preview to see the evaluation.</div></section>
<script>
const base=@json(url('/admin/practice-preview')),caseId=@json($case->id);
let pc,stream,channel,id,tail=Promise.resolve(),pending=[],finishing=false;
const status=document.querySelector('#status');
async function request(path,data){const r=await fetch(base+path,{method:data===undefined?'GET':'POST',headers:{'Accept':'application/json','Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content},body:data===undefined?undefined:JSON.stringify(data)});const j=await r.json();if(!r.ok)throw Error(j.message||'Request failed');return j.data;}
function save(role,body,item_id){const entry={conversation_id:id,role,body,item_id};pending.push(entry);const p=document.createElement('p');p.textContent=role+': '+body;document.querySelector('#transcript').append(p);tail=tail.then(flush).catch(e=>{status.textContent=e.message;});}
async function flush(){while(pending.length){await request('/session/transcript',pending[0]);pending.shift();}}
function stop(){stream?.getTracks().forEach(t=>t.stop());pc?.close();}
async function finish(){if(finishing)return;finishing=true;stop();status.textContent='Preparing feedback…';try{await tail;await flush();await request('/session/'+id+'/finish',{});poll();}catch(e){status.textContent=e.message;finishing=false;}}
async function poll(){try{const a=await request('/session/'+id);if(a.report){status.textContent='Preview complete';const box=document.querySelector('#report');box.textContent='';const heading=document.createElement('h3');heading.textContent=(a.report.provisional?'Provisional feedback':'Feedback')+' · '+(a.report.score??'—')+'/100';box.append(heading);const summary=document.createElement('p');summary.textContent=a.report.summary;box.append(summary);for(const c of a.report.criteria){const p=document.createElement('p');p.textContent=c.text+' — '+c.status+': '+c.feedback;box.append(p);for(const quote of c.excerpts??[]){const q=document.createElement('blockquote');q.textContent=quote.role+': '+quote.text;box.append(q);}}}else if(a.status==='evaluation_failed'){status.textContent='Evaluation failed. Finish again to retry.';finishing=false;}else setTimeout(poll,3000);}catch(e){status.textContent=e.message;}}
document.querySelector('#finish').onclick=finish;
document.querySelector('#start').onclick=async()=>{document.querySelector('#start').disabled=true;try{
 const conversation=await request('/'+caseId+'/start',{});id=conversation.id;
 const secret=await request('/session/voice',{conversation_id:id});pc=new RTCPeerConnection();const audio=document.createElement('audio');audio.autoplay=true;pc.ontrack=e=>{audio.srcObject=e.streams[0];};stream=await navigator.mediaDevices.getUserMedia({audio:true});stream.getTracks().forEach(t=>pc.addTrack(t,stream));channel=pc.createDataChannel('oai-events');
 channel.onopen=()=>{status.textContent='Connected. Speak as the doctor.';document.querySelector('#finish').disabled=false;channel.send(JSON.stringify({type:'response.create'}));};
 channel.onmessage=async e=>{const event=JSON.parse(e.data);if(event.type==='conversation.item.input_audio_transcription.completed')save('user',event.transcript,event.item_id);if(event.type==='response.output_audio_transcript.done')save('assistant',event.transcript,event.item_id);
 if(event.type==='response.function_call_arguments.done'){try{if(event.name!=='record_practice_event')throw Error('Unknown action');const result=await request('/session/'+id+'/events',{...JSON.parse(event.arguments),event_key:event.call_id});channel.send(JSON.stringify({type:'conversation.item.create',item:{type:'function_call_output',call_id:event.call_id,output:JSON.stringify(result)}}));if(result.kind==='finish_requested')setTimeout(finish,500);else channel.send(JSON.stringify({type:'response.create'}));}catch(error){status.textContent=error.message;}}
 if(event.type==='error')status.textContent=event.error?.message||'Voice error';};
 const offer=await pc.createOffer();await pc.setLocalDescription(offer);const r=await fetch(secret.call_url,{method:'POST',headers:{Authorization:'Bearer '+secret.value,'Content-Type':'application/sdp'},body:offer.sdp});if(!r.ok)throw Error('Could not connect voice session');await pc.setRemoteDescription({type:'answer',sdp:await r.text()});
}catch(e){stop();status.textContent=e.message;document.querySelector('#start').disabled=false;}};
window.addEventListener('beforeunload',stop);
</script></body></html>
